const { exec } = require('child_process');
const allowedCommands = ['ls', 'pwd', 'echo'];
if (allowedCommands.includes(req.body.command)) {
    exec(req.body.command, (error, stdout, stderr) => {
        if (error) {
            res.status(500).send(`Error: ${error.message}`);
            return;
        }
        res.send(stdout);
    });
} else {
    res.status(403).send('Invalid command');
}

